
package com.example.cropcare

import android.content.Context

/**
 * Compatibility helper for older CropCare screens.
 *
 * Client-generated soil warnings are paused
 * until sensor calibration, units and fertilizer
 * thresholds have been validated.
 *
 * Trusted status alerts are generated by the
 * ASP.NET Core ingestion endpoint after a
 * verified device submits readings.
 */
object NotificationHelper {

    @Suppress("UNUSED_PARAMETER")
    fun checkAndTriggerSoilAlerts(
        context: Context,
        zoneName: String,
        n: Double,
        p: Double,
        k: Double,
        moisture: Double,
        ph: Double,
        recommendationSummary: String
    ) {
        // Intentionally disabled for now.
    }

    @Suppress("UNUSED_PARAMETER")
    fun checkAndTriggerOfflineSensorAlert(
        context: Context,
        zoneName: String,
        sensorName: String
    ) {
        // Future scheduled backend alert.
    }
}
